class Motor:
    def __init__(self, id):
        self._id = 2 * id

    def rotate(self, s):
        v = abs(s)
        if s > 0:
            self._w(0, v)    
        elif s < 0:
            self._w(1, v) 
        else:   
            self._w(0, 0)    


